// The production build type-checks only its own generated types (2026-11-09).
//
// Twice a deleted route broke the next deploy (enterprise/route.ts, then
// [locale]/free-tools/reddit-threads/route.ts): the deploy builds into
// .next-build, but tsconfig.json also includes .next/types — the LIVE build's
// validator.ts, generated by the previous deploy, which imports every route
// that existed then. next.config.ts now points .next-build builds at
// tsconfig.build.json, which includes only .next-build's types. These tests
// pin that, and replay the failure in a throwaway project with TypeScript's
// own config parser.
import { mkdirSync, mkdtempSync, readFileSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import ts from "typescript";
import { describe, expect, it } from "vitest";

const ROOT = join(__dirname, "..");
const read = (f: string) => readFileSync(join(ROOT, f), "utf8");

function parse(configPath: string): ts.ParsedCommandLine {
  const parsed = ts.getParsedCommandLineOfConfigFile(configPath, {}, { ...ts.sys, onUnRecoverableConfigFileDiagnostic: (d) => { throw new Error(String(d.messageText)); } });
  if (!parsed) throw new Error(`could not parse ${configPath}`);
  return parsed;
}

describe("the production build's tsconfig", () => {
  it("next.config.ts selects tsconfig.build.json for the deploy's .next-build, tsconfig.json otherwise", () => {
    const src = read("next.config.ts");
    expect(src).toMatch(/tsconfigPath:\s*distDir === "\.next-build" \? "tsconfig\.build\.json" : "tsconfig\.json"/);
    expect(read("scripts/deploy.sh")).toMatch(/NEXT_DIST_DIR=\.next-build/);
  });

  it("extends tsconfig.json (so Next never rewrites it) and includes no dist dir but .next-build", () => {
    const raw = ts.parseConfigFileTextToJson("tsconfig.build.json", read("tsconfig.build.json"));
    expect(raw.error).toBeUndefined();
    const cfg = raw.config as { extends: string; include: string[]; exclude: string[] };
    expect(cfg.extends).toBe("./tsconfig.json");
    const distGlobs = cfg.include.filter((g) => g.startsWith(".next"));
    expect(distGlobs.sort()).toEqual([".next-build/dev/types/**/*.ts", ".next-build/types/**/*.ts"]);
    for (const d of [".next", ".next-check", ".next-prev"]) expect(cfg.exclude).toContain(d);
  });

  it("checks exactly the same sources as tsconfig.json", () => {
    const src = (p: ts.ParsedCommandLine) => p.fileNames.filter((f) => f.startsWith(join(ROOT, "src/"))).sort();
    expect(src(parse(join(ROOT, "tsconfig.build.json")))).toEqual(src(parse(join(ROOT, "tsconfig.json"))));
  });

  it("a route deleted since the live build: the stale validators are not in the build's program", () => {
    // A throwaway project shaped like the box after a deploy: the live .next
    // and a scratch .next-check hold validators importing a route that no
    // longer exists; .next-build holds the fresh one.
    const dir = mkdtempSync(join(tmpdir(), "build-tsconfig-"));
    const stale = 'import "../../src/app/api/deleted/route.js";\n';
    for (const d of [".next/types", ".next-check/types", ".next-prev/types", ".next-build/types", "src/app/api/kept"]) mkdirSync(join(dir, d), { recursive: true });
    for (const d of [".next", ".next-check", ".next-prev"]) writeFileSync(join(dir, d, "types/validator.ts"), stale);
    writeFileSync(join(dir, ".next-build/types/validator.ts"), 'import "../../src/app/api/kept/route.js";\n');
    writeFileSync(join(dir, "src/app/api/kept/route.ts"), "export const GET = () => new Response();\n");
    writeFileSync(join(dir, "next-env.d.ts"), '/// <reference types="node" />\n');
    // The real tsconfig.json's include list, as Next has accumulated it.
    writeFileSync(join(dir, "tsconfig.json"), read("tsconfig.json"));
    writeFileSync(join(dir, "tsconfig.build.json"), read("tsconfig.build.json"));

    const full = parse(join(dir, "tsconfig.json")).fileNames;
    const build = parse(join(dir, "tsconfig.build.json")).fileNames;
    const rel = (fs: string[]) => fs.map((f) => f.slice(dir.length + 1)).filter((f) => f.startsWith(".next")).sort();

    // The old config pulls the stale validators in: the deploy failure.
    expect(rel(full)).toEqual(expect.arrayContaining([".next-check/types/validator.ts", ".next/types/validator.ts"]));
    // The build config sees only this build's.
    expect(rel(build)).toEqual([".next-build/types/validator.ts"]);
  });
});
